/**
 * Bunny Loader mod API declarations.
 * Runtime API names and hooks are mirrored from the Bunny Loader JavaScript runtime.
 * Managed Terraria objects have partial structural types; uncovered objects use any.
 * No game assemblies or proprietary DLLs are required.
 */

interface BlRef<T> { value: T; toString(): string; }
declare const Rectangle: RectangleConstructor;
declare const Ref: { new<T>(value: T): BlRef<T> };
type BlItemRef = BlRef<BlItem>;
type BlVectorLike = Vector2 | { X: number; Y: number };
type BlMaybe<T> = T | null | undefined;
type BlHookOriginal = (...args: any[]) => any;
type BlHookCallback = (original: BlHookOriginal, ...args: any[]) => any;

type BlItem = TerrariaItemMembers;
interface BlPlayer extends BlPlayerRuntimeMembers {}
interface BlNPC extends BlNPCRuntimeMembers {}
interface BlProjectile extends BlProjectileRuntimeMembers {}
interface BlItemStatic extends TerrariaItemStatics {}
interface BlPlayerStatic extends BlPlayerStaticMembers {}
interface BlNPCStatic extends BlNPCStaticMembers {}
interface BlProjectileStatic extends BlProjectileStaticMembers {}

